function findMiddleIndex(nums) {
  // Add up both sides from scratch for every index.
  for (let i = 0; i < nums.length; i++) {
    let before = 0;
    let after = 0;
    for (let j = 0; j < i; j++) before += nums[j];
    for (let j = i + 1; j < nums.length; j++) after += nums[j];
    if (before === after) return i;
  }
  return -1;
}

