function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 80 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 8);
  const span = large ? 1000 : (rand() < 0.5 ? 3 : 10);
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  // Usually plant a middle index at k by nudging elements (within range) until the two sides balance.
  if (rand() < 0.7) {
    const k = Math.floor(rand() * n);
    let diff = 0;
    for (let i = 0; i < n; i++) {
      if (i < k) diff += nums[i];
      else if (i > k) diff -= nums[i];
    }
    for (let tries = 0; diff !== 0 && n > 1 && tries < 2000; tries++) {
      const j = Math.floor(rand() * n);
      if (j === k) continue;
      const changed = Math.max(-span, Math.min(span, j < k ? nums[j] - diff : nums[j] + diff));
      diff += j < k ? changed - nums[j] : nums[j] - changed;
      nums[j] = changed;
    }
  }
  return [nums];
}
